import "forge-std/Test.sol";
import "forge-std/console.sol";

/**
 * @title AGL Offensive Security - REAL Exploit PoC
 * @notice Vulnerability Type: generic
 * @dev Contract: ActionsRouter
 * @dev Function: unknown
 * @dev Description: 🚨 CRITICAL: Unprotected Money Flow! Found 4 money movement functions without access control. Patterns: ['transferFrom', 'mint', 'mint', 'mint']
