            abi.encodeWithSignature("grantRole(bytes32,address)", bytes32(0), attacker)
        );
        if (success2) {
            console.log("CRITICAL: Role granted by non-admin!");
            bypassSuccessful = true;
        }

        // Attempt 3: Transfer ownership
        (bool success3,) = targetAddress.call(
            abi.encodeWithSignature("transferOwnership(address)", attacker)
        );
        if (success3) {
            console.log("CRITICAL: Ownership transferred by non-owner!");
            bypassSuccessful = true;
