        _logResults("AccessControl_Bypass", bypassSuccessful);

        if (bypassSuccessful) {
            console.log("ACCESS CONTROL VULNERABILITY CONFIRMED!");
            assertTrue(true, "Access control bypass successful");
        }
    }


    // Helper: Check if exploit was profitable
    function _checkProfit() internal view returns (bool profitable, uint256 profit) {
        uint256 finalBalance = attacker.balance;
        if (finalBalance > attackerInitialBalance) {
            return (true, finalBalance - attackerInitialBalance);
        }
        return (false, 0);
    }

    // Helper: Log exploit results
    function _logResults(string memory testName, bool success) internal view {
        console.log("");
        console.log("--- Results:", testName, "---");
        console.log("Exploit Success:", success);
        (bool profitable, uint256 profit) = _checkProfit();
        if (profitable) {
            console.log("PROFIT EXTRACTED:", profit / 1e18, "ETH");
        }
        console.log("Final Attacker Balance:", attacker.balance / 1e18, "ETH");
