            console.log("   Owner:", ownerAddr);
        } catch {}

        try poolManager.protocolFeeController() returns (address c) {
            console.log("   Fee Controller:", c);
        } catch {}

        console.log("   [PASS] PoolManager is accessible");
    }

    function test_02_UnlockMechanism() public {
