interface IPoolManager {
    function unlock(bytes calldata data) external returns (bytes memory);
    function isUnlocked() external view returns (bool);
    function protocolFeesAccrued(address currency) external view returns (uint256);
    function protocolFeeController() external view returns (address);
    function owner() external view returns (address);
    function balanceOf(address owner, uint256 id) external view returns (uint256);
}

interface IUnlockCallback {
    function unlockCallback(bytes calldata data) external returns (bytes memory);
}

contract UnlockExploiter is IUnlockCallback {
    IPoolManager public poolManager;
    address public owner;
    uint256 public callbackCount;
    bool public exploitMode;

    constructor(address _poolManager) {
        poolManager = IPoolManager(_poolManager);
        owner = msg.sender;
    }

    function setExploitMode(bool _mode) external {
        require(msg.sender == owner);
        exploitMode = _mode;
    }

    function triggerUnlock(bytes calldata data) external returns (bytes memory) {
        return poolManager.unlock(data);
    }

    function unlockCallback(bytes calldata data) external override returns (bytes memory) {
        require(msg.sender == address(poolManager), "Only PoolManager");
        callbackCount++;
        return data;
    }

    receive() external payable {}
}

