pragma solidity ^0.8.20;

/**
 * @title HookMiner
 * @notice Utility to find CREATE2 salt for deploying hooks with specific address flags
 */
library HookMiner {
    /// @notice Find a salt that produces a hook address with the required flags
    /// @param deployer The address that will deploy the hook
    /// @param flags The required hook permission flags
    /// @param creationCode The creation code of the hook contract
    /// @param constructorArgs The encoded constructor arguments
    /// @return hookAddress The address of the hook
    /// @return salt The salt to use with CREATE2
    function find(
        address deployer,
        uint160 flags,
        bytes memory creationCode,
        bytes memory constructorArgs
    ) internal pure returns (address hookAddress, bytes32 salt) {
        bytes memory bytecode = abi.encodePacked(creationCode, constructorArgs);
        bytes32 bytecodeHash = keccak256(bytecode);

        // Search for salt
        for (uint256 i = 0; i < 10000; i++) {
            salt = bytes32(i);
            hookAddress = computeAddress(deployer, salt, bytecodeHash);

            // Check if address has the required flags in lowest bits
            if (uint160(hookAddress) & flags == flags) {
                return (hookAddress, salt);
            }
        }

        revert("Could not find salt for required flags");
    }

    /// @notice Compute CREATE2 address
    function computeAddress(
        address deployer,
        bytes32 salt,
        bytes32 bytecodeHash
    ) internal pure returns (address) {
        return address(uint160(uint256(keccak256(
            abi.encodePacked(bytes1(0xff), deployer, salt, bytecodeHash)
        ))));
    }
}

